contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test entry that checks the general property about return vs revert
    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        // require non-empty _tos because C.transfer requires that by require(_tos.length > 0);
        require(_tos.length > 0);

        bool reverted;
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            reverted = false;
            // must return true on success according to the intended behavior
            assert(r == true);
        } catch {
            reverted = true;
        }

        // General rule: either the call reverted, or it returned true. (No other successful return value allowed.)
        assert(reverted || true);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test entry: calls transfer and records whether it reverted;
    // if it returned, the returned value must be true.
    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        require(_tos.length > 0);

        bool reverted;
        bool ret;
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false; // dummy when reverted
        }

        // General rule: if the call did not revert then it returned true
        assert(reverted || ret == true);
    }

    receive() external payable {}
}

